static TEST_COUNTER: AtomicU64 = AtomicU64::new(0);

fn unique_id(prefix: &str) -> String {
    let counter = TEST_COUNTER.fetch_add(1, Ordering::Relaxed);
    let nanos = SystemTime::now()
        .duration_since(SystemTime::UNIX_EPOCH)
        .expect("the system clock must be after the Unix epoch")
        .as_nanos();
    format!("{prefix}-{nanos}-{counter}")
}

async fn enroll_repository(
    database_url: &str,
    tenant_id: &str,
    repository_id: &str,
    unique: &str,
) -> String {
    let seed: [u8; 32] = Sha256::digest(format!("key-{unique}").as_bytes()).into();
    let signing_key = SigningKey::from_bytes(&seed);
    let public_key = signing_key.verifying_key().to_bytes();
    let request_id = format!("request-{unique}");
    let node_id = format!("node-{unique}");
    let fingerprint = public_key_fingerprint(&public_key);
    let submission = EnrollmentSubmission {
        request_id: request_id.clone(),
        tenant_id: tenant_id.to_string(),
        repository_id: repository_id.to_string(),
        proposed_node_id: node_id.clone(),
        display_name: "Evidence API integration node".to_string(),
        public_key: public_key.to_vec(),
        public_key_fingerprint: fingerprint.clone(),
        requested_capabilities: vec!["synchronize".to_string()],
        created_at: "2026-01-01T00:00:00Z".to_string(),
        expires_at: "2030-01-01T00:00:00Z".to_string(),
    };
    let request = ActivationChallengeRequest {
        request_id,
        tenant_id: tenant_id.to_string(),
        repository_id: repository_id.to_string(),
        proposed_node_id: node_id.clone(),
        public_key_fingerprint: fingerprint.clone(),
    };
    let mut enrollment = EnrollmentStore::connect(database_url)
        .await
        .expect("connect enrollment store");
    enrollment
        .submit(&submission)
        .await
        .expect("submit enrollment");
    enrollment
        .approve(&EnrollmentApproval {
            request_id: request.request_id.clone(),
            tenant_id: tenant_id.to_string(),
            repository_id: repository_id.to_string(),
            public_key_fingerprint: fingerprint.clone(),
            approved_capabilities: submission.requested_capabilities.clone(),
            approved_by: "evidence-api-integration-administrator".to_string(),
        })
        .await
        .expect("approve enrollment");
    let nonce: [u8; 32] = Sha256::digest(format!("nonce-{unique}").as_bytes()).into();
    let challenge = enrollment
        .issue_challenge(&request, &nonce, SystemTime::now())
        .await
        .expect("issue enrollment challenge");
    let signature = signing_key.sign(&activation_challenge_bytes(
        &challenge.nonce,
        &request.request_id,
        &request.tenant_id,
        &request.repository_id,
        &request.proposed_node_id,
        &request.public_key_fingerprint,
    ));
    enrollment
        .activate(
            &EnrollmentActivation {
                request,
                nonce: challenge.nonce,
                signature: signature.to_bytes().to_vec(),
            },
            &format!("receipt-{unique}"),
            &format!("signing-key-{unique}"),
            SystemTime::now(),
        )
        .await
        .expect("activate enrollment");

    node_id
}

async fn application(database_url: &str, tenant_id: &str) -> axum::Router {
    let evidence = Arc::new(
        BridgeEvidenceStore::connect(database_url)
            .await
            .expect("connect Bridge Evidence store"),
    );
    let fleet = Arc::new(
        FleetStore::connect(database_url)
            .await
            .expect("connect Bridge Fleet store"),
    );
    evidence_routes(EvidenceApiState::new(
        evidence,
        fleet,
        Arc::<str>::from(tenant_id.to_string()),
    ))
}

async fn body_json(response: axum::response::Response) -> Value {
    let body = to_bytes(response.into_body(), 1_048_576)
        .await
        .expect("read Bridge response body");
    serde_json::from_slice(&body).expect("parse Bridge JSON response")
}

// Regression: the Evidence Board must read only its tenant's enrolled
// repository, project structured codes into JSON, and redact session labels
// from the audit export rather than exposing a raw record dump.
#[tokio::test]
async fn tenant_scoped_evidence_board_and_export_remain_redacted() {
    let Ok(database_url) = std::env::var("ACKPLANE_TEST_DATABASE_URL") else {
        println!("skipped: ACKPLANE_TEST_DATABASE_URL not set");
        return;
    };
    let unique = unique_id("evidence-api");
    let tenant_id = format!("tenant-{unique}");
    let repository_id = format!("repository-{unique}");
    let task_id = format!("task:{unique}");
    let node_id = enroll_repository(&database_url, &tenant_id, &repository_id, &unique).await;
    let raw_session_label = "session:v1:evidence-api-private";
    let evidence_store = EvidenceStore::connect(&database_url)
        .await
        .expect("connect Evidence store");
    let evidence = evidence_store
        .record(RecordEvidenceRequest {
            tenant_id: tenant_id.clone(),
            repository_id: repository_id.clone(),
            task_id: task_id.clone(),
            kind: EvidenceKind::Commit,
            source_ref: format!("commit:{unique}"),
            content_digest: vec![7; 32],
            observed_at: SystemTime::now(),
            reported_agent_session_id: raw_session_label.to_string(),
            recorded_by: node_id.clone(),
            idempotency_key: format!("evidence-{unique}"),
            reported_constitution_version: Some("constitution:v4".to_string()),
        })
        .await
        .expect("record Evidence");
    evidence_store
        .record_conformance(RecordConformanceRequest {
            tenant_id: tenant_id.clone(),
            repository_id: repository_id.clone(),
            task_id: task_id.clone(),
            evidence_id: evidence.record.evidence_id.clone(),
            verdict: ConformanceVerdict::Drift,
            finding_count: 1,
            findings_digest: vec![8; 32],
            finding_codes: vec![ConformanceFindingCode::PolicyDrift],
            reported_checked_at: SystemTime::now(),
            evaluated_by: node_id,
            idempotency_key: format!("conformance-{unique}"),
            reported_constitution_version: Some("constitution:v4".to_string()),
        })
        .await
        .expect("record finding-coded conformance");

    let route =
        format!("/api/v1/repositories/{repository_id}/tasks/{task_id}/evidence-board?limit=20");
    let board = application(&database_url, &tenant_id)
        .await
        .oneshot(
            Request::builder()
                .uri(&route)
                .body(Body::empty())
                .expect("build Evidence Board request"),
        )
        .await
        .expect("serve Evidence Board route");
    assert_eq!(board.status(), StatusCode::OK);
    let board = body_json(board).await;
    assert_eq!(
        board["status"],
        json!({
            "evidence": "complete",
            "conformance": "complete",
            "review": "pending",
            "freshness": "fresh",
            "latest_recorded_at_seconds": board["status"]["latest_recorded_at_seconds"],
        })
    );
    assert_eq!(
        board["conformance"]["entries"][0]["finding_codes"],
        json!(["policy_drift"])
    );
    assert_eq!(
        board["evidence"]["entries"][0]["reported_constitution_version"],
        json!("constitution:v4")
    );

    let export = application(&database_url, &tenant_id)
        .await
        .oneshot(
            Request::builder()
                .uri(format!(
                    "/api/v1/repositories/{repository_id}/tasks/{task_id}/evidence-board/export?limit=20"
                ))
                .body(Body::empty())
                .expect("build Evidence audit export request"),
        )
        .await
        .expect("serve Evidence audit export route");
    assert_eq!(export.status(), StatusCode::OK);
    let export = body_json(export).await;
    let expected_session_fingerprint = format!(
        "sha256:{}",
        Sha256::digest(raw_session_label.as_bytes())
            .iter()
            .map(|byte| format!("{byte:02x}"))
            .collect::<String>()
    );
    assert_eq!(
        export["evidence"][0]["reported_agent_session_fingerprint"],
        json!(expected_session_fingerprint)
    );
    assert!(export["evidence"][0]
        .get("reported_agent_session_id")
        .is_none());
    assert!(export["evidence"][0].get("idempotency_key").is_none());

    let foreign = application(&database_url, &format!("{tenant_id}-other"))
        .await
        .oneshot(
            Request::builder()
                .uri(&route)
                .body(Body::empty())
                .expect("build foreign tenant request"),
        )
        .await
        .expect("serve foreign tenant route");
    assert_eq!(foreign.status(), StatusCode::NOT_FOUND);
}
